<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { Activity, Terminal, Layers, Minimize2, ChartNoAxesColumn } from 'lucide-vue-next'
import VueBitsLightPillar from './vendor/VueBitsLightPillar.vue'
import { performanceSeconds, performanceTaskView, type PerformanceDays, type PerformanceScope, type PerformanceStatistic } from './performance-story'
const props = withDefaults(defineProps<{ initialView?: 'tasks' | 'tools' | 'parallel' | 'compaction' }>(), { initialView: 'tasks' })
const selected = ref<string>(props.initialView), metric = ref(0)
watch(() => props.initialView, value => { selected.value = value })
const metrics = [
  { title:'首 Token 等待',value:'1.8',unit:'秒',color:'#2563eb',detail:'首响应等待中位数 1.8 秒 · p95 4.6 秒 · 24 个正常完成样本。' },
  { title:'轮耗时',value:'42.6',unit:'秒',color:'#009588',detail:'完整一轮的中位数 42.6 秒 · p95 96.4 秒，包含工具与等待。' },
  { title:'工具总耗时',value:'386',unit:'秒',color:'#8050d3',detail:'已记录的 46 次完整工具执行累计，可并行，不等于任务墙钟时间。' },
  { title:'异常结束',value:'1',unit:'次',color:'#be3d6d',detail:'正常完成 24 次、失败 1 次，失败率 4%；中断单独统计。' },
  { title:'任务停止',value:'2',unit:'次',color:'#c07305',detail:'停止或关闭会话所产生的已记录中断，不计入失败率。' },
]
const stories = [
  { id:'tasks', title:'任务耗时',icon:ChartNoAxesColumn,lead:'一次任务，\n等了多久。',text:'看逐次任务，再看每日总量与每任务平均。主会话、子 Agent 各自统计，结合中位数与长尾再做判断。' },
  { id:'tools', title:'工具执行',icon:Terminal,lead:'慢在哪里，\n有据可查。',text:'首响应在等，工具在跑，还是任务已经停止？把等待拆开，才能看清发生了什么。' },
  { id:'parallel',title:'Agent 并行度',icon:Layers,lead:'一起拉磨，\n各有进度。',text:'正在执行几路、峰值开到多少、重叠了多久，按主会话或子 Agent 分组，看清各自的协作节奏。' },
  { id:'compaction',title:'压缩与推理',icon:Minimize2,lead:'上下文变化，\n也有记录。',text:'看清压缩发生的时间，以及输出中推理 Token 的比例。每个判断，都能回到样本。' },
]
const current = computed(() => stories.find(item=>item.id === selected.value)!)
const tool = ref('exec_command')
const tools = [{name:'exec_command',count:24,total:236,p50:5.2,p95:28.4},{name:'apply_patch',count:14,total:98,p50:4.8,p95:16.2},{name:'read_file',count:8,total:52,p50:5.1,p95:11.3}]
const activeTool = computed(() => tools.find(item=>item.name === tool.value)!)
const lane = ref(0)
const lanes = [{name:'主会话 · 界面',start:0,width:88},{name:'主会话 · 接口',start:12,width:57},{name:'主会话 · 文档',start:23,width:52},{name:'主会话 · 验证',start:48,width:45}]
const taskDays = ref<PerformanceDays>(1), taskScope = ref<PerformanceScope>('main'), taskStatistic = ref<PerformanceStatistic>('total')
const taskView = computed(() => performanceTaskView(taskDays.value, taskScope.value, taskStatistic.value))
const taskOffset = ref(12), taskPoint = ref(0)
const taskPoints = computed(() => taskDays.value === 1 ? taskView.value.points.slice(taskOffset.value, taskOffset.value + 12) : taskView.value.points)
const taskActive = computed(() => taskPoints.value[Math.min(taskPoint.value, taskPoints.value.length - 1)]!)
const taskRangeLabel = computed(() => taskDays.value === 1 ? '今天' : `${taskDays.value} 天`)
const taskScopeLabel = computed(() => taskScope.value === 'main' ? '主会话' : '子 Agent')
const taskModeLabel = computed(() => taskDays.value === 1 ? '每柱一次' : taskStatistic.value === 'total' ? '每日总耗时' : '每任务平均耗时')
const taskColors = ['#16b8a6','#4277f5','#8b68eb','#e7a447','#db6799','#4aa6ce']
watch([taskDays, taskScope], () => { taskOffset.value = Math.max(0, taskView.value.points.length - 12); taskPoint.value = 0 })
watch(taskOffset, () => { taskPoint.value = 0 })
function taskKey(index: number, event: KeyboardEvent) {
  const last = taskPoints.value.length - 1
  const next = event.key === 'ArrowRight' ? Math.min(last, index + 1) : event.key === 'ArrowLeft' ? Math.max(0, index - 1) : event.key === 'Home' ? 0 : event.key === 'End' ? last : null
  if (next === null) return
  event.preventDefault(); taskPoint.value = next
  ;(event.currentTarget as HTMLElement).parentElement?.querySelector<HTMLButtonElement>(`[data-task-index="${next}"]`)?.focus()
}
</script>
<template>
<section id="performance" class="performance-story" aria-labelledby="performance-title">
  <div class="performance-light" aria-hidden="true"><VueBitsLightPillar :interactive="true" :intensity=".72" :pillar-rotation="24" :pillar-width="3.7" quality="medium" /></div>
  <div class="performance-content">
    <div class="performance-heading"><div><h2 id="performance-title">{{ current.lead }}</h2><p>{{ current.text }}</p></div><nav aria-label="模型性能展示"><button v-for="item in stories" :key="item.id" type="button" :aria-pressed="selected === item.id" @click="selected=item.id"><component :is="item.icon" :size="17"/>{{ item.title }}</button></nav></div>
    <div class="performance-native" aria-label="Codex 模型性能界面局部重绘，示例数据"><header><h3><Activity :size="16"/>模型性能</h3><span>Codex · {{ selected === 'tasks' ? `${taskRangeLabel} · ${taskScopeLabel}` : '今天 · 主会话' }}</span></header>
      <template v-if="selected !== 'tasks'"><div class="performance-metrics"><button v-for="(item,index) in metrics" :key="item.title" type="button" :aria-pressed="metric === index" @click="metric=index"><span>{{ item.title }}</span><strong :style="{ color:item.color }">{{ item.value }}<small>{{ item.unit }}</small></strong></button></div><p class="performance-metric-detail" aria-live="polite">{{ metrics[metric]!.detail }}</p></template>
      <div v-if="selected === 'tasks'" class="performance-task-view">
        <div class="task-controls"><div class="task-segments" role="group" aria-label="任务耗时时间范围"><button v-for="days in ([1,7,30] as const)" :key="days" type="button" :aria-pressed="taskDays === days" @click="taskDays = days">{{ days === 1 ? '今天' : `${days} 天` }}</button></div><div class="task-segments" role="group" aria-label="任务耗时会话对象"><button type="button" :aria-pressed="taskScope === 'main'" @click="taskScope = 'main'">主会话</button><button type="button" :aria-pressed="taskScope === 'subagent'" @click="taskScope = 'subagent'">子 Agent</button></div></div>
        <dl class="task-summary" aria-live="polite" aria-atomic="true"><div><dt>完整计时</dt><dd>{{ taskView.summary.count }}<small>/ {{ taskView.recordCount }} 次</small></dd></div><div><dt>任务中位数</dt><dd>{{ performanceSeconds(taskView.summary.median) }}<small>秒</small></dd></div><div><dt>95% 以内</dt><dd>{{ performanceSeconds(taskView.summary.p95) }}<small>秒</small></dd></div><div><dt>每任务平均</dt><dd>{{ performanceSeconds(taskView.summary.mean) }}<small>秒</small></dd></div></dl>
        <div class="task-chart-card"><div class="task-chart-heading"><h4>任务耗时</h4><div v-if="taskDays !== 1" class="task-segments task-statistic" role="group" aria-label="任务耗时统计方式"><button type="button" :aria-pressed="taskStatistic === 'total'" @click="taskStatistic = 'total'">每日总耗时</button><button type="button" :aria-pressed="taskStatistic === 'mean'" @click="taskStatistic = 'mean'">每任务平均耗时</button></div><span v-else>每柱一次 · 第 {{ taskOffset + 1 }}–{{ taskOffset + taskPoints.length }} / {{ taskView.points.length }} 次</span></div>
          <div class="task-chart" :aria-label="`${taskScopeLabel}，${taskRangeLabel}，${taskModeLabel}，单位秒`"><div class="task-y-axis" aria-hidden="true"><span>{{ performanceSeconds(taskView.axisMax) }}s</span><span>{{ performanceSeconds(taskView.axisMax / 2) }}s</span><span>0</span></div><div class="task-plot" :style="{ gridTemplateColumns: `repeat(${taskPoints.length},minmax(0,1fr))` }"><button v-for="(point,index) in taskPoints" :key="point.id" type="button" :data-task-index="index" :tabindex="taskPoint === index ? 0 : -1" :aria-pressed="taskPoint === index" :aria-label="`${point.label}，${point.value === null ? '未记录耗时' : `${performanceSeconds(point.value)} 秒`}，${point.detail}`" aria-describedby="performance-task-detail" @mouseenter="taskPoint=index" @focus="taskPoint=index" @click="taskPoint=index" @keydown="taskKey(index, $event)"><i v-if="point.value !== null" :style="{ height:`${Math.max(1, point.value / taskView.axisMax * 100)}%`,background:taskColors[index % taskColors.length] }"></i><em v-else aria-hidden="true">—</em><span v-if="index === 0 || index === taskPoints.length - 1 || (taskDays !== 1 && index % Math.ceil(taskPoints.length / 5) === 0)" aria-hidden="true">{{ point.label }}</span></button></div></div>
          <input v-if="taskDays === 1 && taskView.points.length > 12" v-model.number="taskOffset" class="task-window" type="range" min="0" :max="taskView.points.length - 12" step="1" aria-label="逐任务图可见选区起点" :aria-valuetext="`第 ${taskOffset + 1} 至 ${taskOffset + taskPoints.length} 个已计时任务`"/>
          <p id="performance-task-detail" class="task-detail" aria-live="polite" aria-atomic="true"><strong>{{ taskActive.label }}<span>{{ taskActive.value === null ? '未记录耗时' : `${performanceSeconds(taskActive.value)} 秒` }}</span></strong><span>{{ taskActive.detail }}</span></p>
        </div>
      </div>
      <div v-else-if="selected === 'tools'" class="performance-tools"><div class="performance-tool-list"><h4>工具执行</h4><button v-for="item in tools" :key="item.name" type="button" :aria-pressed="tool === item.name" @click="tool=item.name"><span>{{ item.name }}<small>{{ item.count }} 次执行</small></span><div><i :style="{ transform:`scaleX(${item.total / 236})` }"></i></div><b>{{ item.total }}s</b></button></div><aside><span>{{ activeTool.name }}</span><div><strong>{{ activeTool.p50 }}<small>s</small></strong><span>p50</span><strong>{{ activeTool.p95 }}<small>s</small></strong><span>p95</span></div><p>从中位数看到长尾，<br>再追到具体工具执行。</p></aside></div>
      <div v-else-if="selected === 'parallel'" class="parallel-view"><div class="parallel-stats"><span>执行中<strong>3<small>个会话</small></strong></span><span>区间峰值<strong>4<small>个会话</small></strong></span><span>任务重叠<strong>186<small>秒</small></strong></span></div><div class="parallel-lanes"><button v-for="(item,index) in lanes" :key="item.name" type="button" :aria-pressed="lane === index" @click="lane=index"><span>{{ item.name }}</span><div><i :style="{ left:`${item.start}%`,width:`${item.width}%`,background: ['#2563eb','#0086a8','#8050d3','#c07305'][index] }"></i></div></button></div><p class="performance-footnote">{{ lanes[lane]!.name }}的执行区间 · 按已记录任务边界展示，不代表实时调度</p></div>
      <div v-else class="compaction-view"><article><h4>推理 Token 占比</h4><div class="reasoning-values"><span>推理<strong>10,080<small>60%</small></strong></span><span>普通输出<strong>6,720<small>40%</small></strong></span></div><div class="reasoning-strip"><i></i></div><p>输出总量 16,800 Token</p></article><article><h4>上下文压缩 <small>未计时 1 次</small></h4><div class="compaction-events"><span><i></i><b>09:42</b><strong>2.4 秒</strong></span><span><i></i><b>11:18</b><strong>3.1 秒</strong></span><span><i></i><b>13:36</b><strong>耗时缺失</strong></span></div></article></div>
      <footer>已读取的本机样本 · {{ selected === 'compaction' ? '推理 Token 已包含在输出中，不重复计入。' : '本页数值为示例，实际统计以本机可读取记录为准。' }}</footer>
    </div>
  </div>
</section>
</template>
